{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.BUILDSKILL_DB_PRODUCT_MARKETING_CONSOLIDATED AS WITH sku_map AS ( SELECT * FROM `maplemonk.Buildskill_GS_SKU_MASTER` QUALIFY ROW_NUMBER() OVER (PARTITION BY master_sku) = 1 ), marketing_consolidated AS ( SELECT LOWER(TRIM(channel)) AS channel, DATE(date) AS date, SUM(CAST(spend AS FLOAT64)) AS total_channel_spend FROM `maplemonk.buildskill_wh_MARKETING_CONSOLIDATED` GROUP BY 1,2 ), amazon_channel_spend AS ( SELECT LOWER(\'amazon\') AS channel, DATE(date) AS date, SUM(CAST(spend AS FLOAT64)) AS total_channel_spend FROM `maplemonk.Buildskill_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED` GROUP BY 1,2 ), amazon AS ( SELECT CAST(NULL AS STRING) AS ADSET_NAME, CAST(NULL AS STRING) AS ADSET_ID, CAST(a.AD_ID AS STRING) AS AD_ID, CAST(a.ADGROUPNAME AS STRING) AS AD_NAME, CAST(a.PROFILENAME AS STRING) AS ACCOUNT_NAME, CAST(a.PROFILEID AS STRING) AS ACCOUNT_ID, CAST(a.CAMPAIGNNAME AS STRING) AS CAMPAIGN_NAME, CAST(a.CAMPAIGN_ID AS STRING) AS CAMPAIGN_ID, CAST(a.channel_product_id AS STRING) AS PRODUCT_ID, CAST(NULL AS STRING) AS VARIANT_ID, a.DATE AS DATE, CAST(a.AD_TYPE_1 AS STRING) AS AD_TYPE, CAST(NULL AS STRING) AS AD_STRENGTH, CAST(NULL AS STRING) AS AD_NETWORK_TYPE, CAST(NULL AS STRING) AS AD_FINAL_URL, FORMAT_DATE(\'%A\', a.DATE) AS DAY_OF_WEEK, EXTRACT(YEAR FROM a.DATE) AS YEAR, EXTRACT(MONTH FROM a.DATE) AS MONTH, CAST(\'Amazon\' AS STRING) AS CHANNEL, CAST(a.PROFILENAME AS STRING) AS ACCOUNT, a.clicks AS CLICKS, a.spend AS SPEND, a.impressions AS IMPRESSIONS, a.conversions AS CONVERSIONS, ifnull(a.conversion_value, 0) AS CONVERSION_VALUE, ifnull(a.conversion_value, 0) AS SALES, UPPER(TRIM(sm.master_sku)) AS SKU, UPPER(TRIM(sm.PRODUCT_TITLE)) as product_name, CONCAT(upper(trim(CATEGORY)), \'-\', upper(trim(SUB_CATEGORY))) AS master_category FROM ( SELECT AD_ID, ADGROUPNAME, PROFILEID, CAMPAIGNNAME, CAMPAIGN_ID, profileName, COALESCE( CASE WHEN LENGTH(TRIM(asin)) = 10 THEN TRIM(asin) END, CASE WHEN LENGTH(TRIM(SPLIT(campaignname, \'-\')[SAFE_OFFSET(2)])) = 10 THEN TRIM(SPLIT(campaignname, \'-\')[SAFE_OFFSET(2)]) END) AS channel_product_id, DATE(Date) AS DATE, AD_TYPE_1, SUM(clicks) clicks, SUM(spend) spend, SUM(Impressions) impressions, SUM(ATTRIBUTED_CONVERSIONS_14D) conversions, SUM(ATTRIBUTED_SALES_14D) conversion_value FROM `maplemonk.Buildskill_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED` WHERE channel_product_id IS NOT NULL GROUP BY 1,2,3,4,5,6,7,8,9 ) a LEFT JOIN sku_map sm ON TRIM(LOWER(CAST(a.channel_product_id AS STRING))) = TRIM(LOWER(CAST(sm.ASIN AS STRING))) ), marketing_consolidated_product_intermediate AS ( SELECT * FROM amazon ), category_orders AS ( SELECT DATE_TRUNC(order_date, MONTH) AS month_start, CONCAT(UPPER(TRIM(sm.CATEGORY)), \'-\', UPPER(TRIM(sm.SUB_CATEGORY))) AS master_category, COUNT(DISTINCT order_id) AS total_orders FROM `maplemonk.buildskill_wh_sales_consolidated` s LEFT JOIN `maplemonk.Buildskill_GS_SKU_MASTER` sm ON UPPER(TRIM(s.product_id)) = UPPER(TRIM(sm.asin)) GROUP BY 1,2 ), category_monthly_sales AS ( SELECT d.master_category, DATE_TRUNC(d.DATE, MONTH) AS sales_month, SUM(IFNULL(d.sales,0)) AS monthly_sales, MAX(IFNULL(co.total_orders,0)) AS total_orders FROM marketing_consolidated_product_intermediate d LEFT JOIN category_orders co ON DATE_TRUNC(d.DATE, MONTH) = co.month_start AND d.master_category = co.master_category GROUP BY 1,2 ), category_past_benchmark AS ( SELECT master_category, sales_month, MAX(monthly_sales) OVER (PARTITION BY master_category ORDER BY sales_month ROWS BETWEEN 11 PRECEDING AND CURRENT ROW) AS past_benchmark FROM category_monthly_sales ) SELECT m.*, IFNULL(SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL), 0) AS total_product_lvl_spend, IFNULL(CASE WHEN LOWER(m.channel) LIKE \'%amazon%\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END, 0) AS total_channel_spend, IFNULL(CASE WHEN LOWER(m.channel) LIKE \'%amazon%\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END, 0) - IFNULL(SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL), 0) AS spend_diff, CASE WHEN (CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) > SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL) AND SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL) > 0 THEN ((CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) - SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL)) * (m.conversion_value / SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL)) ELSE 0 END AS allocated_spend_diff, CASE WHEN (CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) > SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL) AND SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL) > 0 THEN m.SPEND + (((CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) - SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL)) * (m.conversion_value / SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL))) ELSE m.SPEND END AS corrected_spend, IFNULL(cpb.past_benchmark,0) AS past_benchmark, IFNULL(co.total_orders,0) AS total_orders, IFNULL(CAST(REPLACE(st.target, \',\', \'\') AS FLOAT64),0) AS monthly_target FROM marketing_consolidated_product_intermediate m LEFT JOIN marketing_consolidated mc ON LOWER(TRIM(CAST(m.channel AS STRING))) = LOWER(TRIM(CAST(mc.channel AS STRING))) AND CAST(m.date AS DATE) = CAST(mc.date AS DATE) LEFT JOIN amazon_channel_spend ac ON LOWER(TRIM(CAST(m.channel AS STRING))) = LOWER(TRIM(CAST(ac.channel AS STRING))) AND CAST(m.date AS DATE) = CAST(ac.date AS DATE) LEFT JOIN category_past_benchmark cpb ON m.master_category = cpb.master_category AND DATE_TRUNC(m.DATE, MONTH) = cpb.sales_month LEFT JOIN category_orders co ON DATE_TRUNC(m.DATE, MONTH) = co.month_start AND UPPER(TRIM(m.master_category)) = UPPER(TRIM(co.master_category)) LEFT JOIN (SELECT * FROM `maplemonk.Buildskill_GS_SKU_Target` WHERE UPPER(TRIM(month)) = UPPER(FORMAT_DATE(\'%B\', CURRENT_DATE()))) st ON UPPER(TRIM(m.sku)) = UPPER(TRIM(st.sku)) ; CREATE OR REPLACE TABLE MAPLEMONK.BUILDSKILL_CATEGORY_MONTHLY_SUMMARY AS WITH daily_category_sales AS ( SELECT DATE, DATE_TRUNC(DATE, MONTH) AS month_start, master_category, SUM(IFNULL(sales,0)) AS daily_sales, SUM(IFNULL(corrected_spend,0)) AS daily_spend, SUM(IFNULL(conversion_value,0)) AS daily_paid_sales, MAX(IFNULL(past_benchmark,0)) AS past_benchmark, MAX(IFNULL(monthly_target,0)) AS monthly_target, SUM(IFNULL(conversions,0)) AS daily_ad_orders, MAX(IFNULL(total_orders,0)) AS total_orders FROM MAPLEMONK.BUILDSKILL_DB_PRODUCT_MARKETING_CONSOLIDATED GROUP BY 1,2,3 ) SELECT month_start, master_category, MAX(past_benchmark) AS past_benchmark, MAX(monthly_target) AS monthly_target, SUM(daily_sales) AS total_sales, SUM(daily_spend) AS total_spend, SUM(daily_paid_sales) AS paid_sales, SAFE_DIVIDE(SUM(daily_spend), SUM(daily_sales)) AS tacos, SAFE_DIVIDE(SUM(daily_spend), SUM(daily_paid_sales)) AS acos, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_sales ELSE 0 END) AS w1_nmv, MAX(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_sales END) AS w1_trending, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_spend ELSE 0 END) AS w1_spend, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_paid_sales ELSE 0 END) AS w1_paid_sales, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_sales ELSE 0 END) AS w2_nmv, MAX(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_sales END) AS w2_trending, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_spend ELSE 0 END) AS w2_spend, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_paid_sales ELSE 0 END) AS w2_paid_sales, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_sales ELSE 0 END) AS w3_nmv, MAX(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_sales END) AS w3_trending, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_spend ELSE 0 END) AS w3_spend, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_paid_sales ELSE 0 END) AS w3_paid_sales, SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_sales ELSE 0 END) AS w4_nmv, MAX(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_sales END) AS w4_trending, SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_spend ELSE 0 END) AS w4_spend, SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_paid_sales ELSE 0 END) AS w4_paid_sales, SUM(daily_ad_orders) AS ad_orders, MAX(total_orders) AS total_orders FROM daily_category_sales GROUP BY 1,2;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
